            'RP': { label: '🟢 RP - Return Part / IQC (Format-1)', bg: 'bg-emerald-100 text-emerald-900 border-emerald-300' },
            'VF/RP': { label: '🟣 VF / RP Combined (รายงานร่วม)', bg: 'bg-purple-100 text-purple-900 border-purple-300' },
