    async function copyUserCredentials(email, pass) {
        const text = `Email: ${email}\nPassword: ${pass}`;
        try {
            if (navigator.clipboard && navigator.clipboard.writeText) {
                await navigator.clipboard.writeText(text);
            } else {
                const textarea = document.createElement('textarea');
                textarea.value = text;
                document.body.appendChild(textarea);
                textarea.select();
                document.execCommand('copy');
                document.body.removeChild(textarea);
            }
            toast("📋 คัดลอกข้อมูลเข้าใช้งานเรียบร้อย", "success");
        } catch (e) {
            toast("คัดลอกไม่สำเร็จ: " + e.message, "error");
        }
    }

    async function toggleForceResetState(userId) {
        const user = _data.users.find(u => String(u.id) === String(userId));
        if (!user) return toast("ไม่พบข้อมูลผู้ใช้งาน", "error");

        const currentVal = !!user.force_reset || !!user.is_reset_key_required;
        const newVal = !currentVal;

        showLoader(true);
        try {
            const clients = getAdminClients();
            for (const client of clients) {
                try {
                    if (userId && !String(userId).startsWith('appr_')) {
                        await client.from('users').update({ 
                            force_reset: newVal, 
                            is_reset_key_required: newVal,
                            updated_at: new Date().toISOString()
                        }).eq('id', userId);
                    }
                } catch (_) {}
                try {
                    if (user.email) {
                        await client.from('users').update({ 
                            force_reset: newVal, 
                            is_reset_key_required: newVal,
                            updated_at: new Date().toISOString()
                        }).eq('email', user.email);
                    }
                } catch (_) {}
            }

            user.force_reset = newVal;
            user.is_reset_key_required = newVal;

            writeAuditLog('USER_FORCE_RESET_TOGGLE', `ปรับสถานะ Force Reset ให้กับ ${user.email}: ${newVal ? 'ENABLED' : 'DISABLED'}`);
            toast(newVal ? "🔑 ตั้งค่าบังคับรีเซ็ตรหัสผ่านแล้ว" : "✅ ยกเลิกการบังคับรีเซ็ตรหัสผ่านแล้ว", "success");
            
            openResetSecurityModal(userId);
            renderTable();
            updateStats();
        } catch (e) {
            toast("ดำเนินการไม่สำเร็จ: " + (e.message || ''), "error");
        }
        showLoader(false);
    }

    async function applyNewSecurityKey(userId) {
        const user = _data.users.find(u => String(u.id) === String(userId));
        if (!user) return toast("ไม่พบข้อมูลผู้ใช้งาน", "error");

        const newPass = document.getElementById('adm-sec-new-pass')?.value.trim();
        if (!newPass) return toast("กรุณาระบุรหัสผ่านใหม่", "error");

        showLoader(true);
        try {
            const clients = getAdminClients();
            const nowIso = new Date().toISOString();
            const payload = {
                email: user.email,
                display_name: user.display_name || resolveOfficialDisplayName(user.email, ''),
                password: newPass,
                role: user.role || 'sqe_support',
                status: user.status || 'active',
                updated_at: nowIso
            };

            for (const client of clients) {
                try {
                    await client.from('users').upsert(payload, { onConflict: 'email' });
                } catch (_) {}
                try {
                    if (userId && !String(userId).startsWith('appr_')) {
                        await client.from('users').update({ 
                            password: newPass,
                            updated_at: nowIso
                        }).eq('id', userId);
                    }
                } catch (_) {}
                try {
                    if (user.email) {
                        await client.from('users').update({ 
                            password: newPass,
                            updated_at: nowIso
                        }).eq('email', user.email);
                    }
                } catch (_) {}
            }

            user.password = newPass;
            user.updated_at = nowIso;

            writeAuditLog('USER_KEY_RESET', `ตั้งค่ารหัสผ่านใหม่ให้กับ ${user.email}`);
            toast("⚡ เปลี่ยนรหัสผ่านใหม่และบันทึกลง Supabase สำเร็จ", "success");
            
            openResetSecurityModal(userId);
            renderTable();
            updateStats();
        } catch (e) {
            toast("เปลี่ยนรหัสผ่านไม่สำเร็จ: " + (e.message || ''), "error");
        }
        showLoader(false);
    }

    async function saveUser() {
        const email = document.getElementById('adm-u-email')?.value.trim();
        let displayName = document.getElementById('adm-u-display-name')?.value.trim();
        const pass = document.getElementById('adm-u-pass')?.value.trim();
        const role = document.getElementById('adm-u-role')?.value || 'sqe_support';

        if (!email || !pass) return toast("กรุณากรอก Email และ Password ให้ครบถ้วน", "error");
        if (!displayName) {
            displayName = resolveOfficialDisplayName(email, '');
        }

        showLoader(true);
        try {
            const clients = getAdminClients();
            const nowIso = new Date().toISOString();
            const payload = {
                email: email,
                display_name: displayName,
                password: pass,
                role: role,
                status: 'active',
                created_at: nowIso,
                updated_at: nowIso
            };

            let success = false;
            for (const client of clients) {
                try {
                    const { data: existUser } = await client.from('users').select('id').ilike('email', email).maybeSingle();
                    if (existUser && existUser.id) {
                        const { error: upErr } = await client.from('users').update({
                            display_name: displayName,
                            password: pass,
                            role: role,
                            status: 'active',
                            updated_at: nowIso
                        }).eq('id', existUser.id);
                        if (!upErr) { success = true; continue; }
                    } else {
                        const { error: insErr } = await client.from('users').insert([payload]);
                        if (!insErr) { success = true; }
                    }
                } catch (_) {}
            }

            const existingIdx = _data.users.findIndex(u => u.email && u.email.toLowerCase() === email.toLowerCase());
            if (existingIdx !== -1) {
                _data.users[existingIdx] = {
                    ..._data.users[existingIdx],
                    display_name: displayName,
                    password: pass,
                    role: role,
                    status: 'active',
                    updated_at: nowIso
                };
            } else {
                _data.users.push({
                    id: 'usr_' + Date.now(),
                    email: email,
                    display_name: displayName,
                    password: pass,
                    role: role,
                    status: 'active',
                    created_at: nowIso,
                    updated_at: nowIso
                });
            }

            writeAuditLog('USER_CREATE', `เพิ่ม/อัปเดตบัญชีพนักงาน: ${email} (${displayName}) สิทธิ์: ${role}`);
            toast("✅ เพิ่มบัญชีพนักงานและบันทึกลง Supabase สำเร็จ", "success");
            closeMasterModal();
            renderTable();
            updateStats();
        } catch (e) {
            console.error(e);
            toast("❌ เพิ่มพนักงานล้มเหลว: " + (e.message || ''), "error");
        }
        showLoader(false);
    }

