        <tr>
            <td style="padding: 0;">
                <img src="cid:non_conformance_img" width="680" style="width: 100%; max-width: 680px; height: auto; display: block; border: 1.5px solid #000; box-sizing: border-box;" alt="Non-conformance Evidence Photo" />
            </td>
        </tr>
